file.content:
    packages: &BTreeMap<PackageId, Package>,
    index: &IdentityIndex,
    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
    ctx: &OpenContext<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> (Vec<DepEdge>, EdgeIndex, EdgeIndex) {
    let mut edges = Vec::new();
    let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
    let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
    let npm_dirs = LazyNpmDirIndex::new(root);

    for pkg in packages.values() {
        for decl in &pkg.manifests {
            if decl.role != ManifestRole::Canonical {
                continue;
            }
            let m = match open_cached(manifest_cache, decl, ctx) {
                Ok(m) => m,
                Err(error) => {
                    diagnostics.push(unresolved(
                        &decl.path,
                        "open its manifest to read its dependencies",
                        error,
                    ));
                    continue;
                }
            };
            {
                for entry in m.iter_dependencies() {
                    let inherited = entry.inherited.then(|| m.inherited_dependency(&entry.name)).flatten();
                    let (spec, declaring_path) = match inherited {
                        Some(dep) => (dep.spec.clone(), dep.declared_in.to_path_buf()),
                        None => (entry.spec.clone(), decl.path.clone()),
                    };

                    let workspace_target = match &spec {
                        DepSpec::WorkspaceProtocol(workspace) => workspace.relative_path().and_then(|relative| {
                            npm_dirs
                                .lookup(packages.values(), &decl.path, relative)
                                .unwrap_or_else(|error| {
                                    diagnostics.push(unresolved(
                                        &decl.path,
                                        "resolve a relative `workspace:` dependency",
                                        error,
                                    ));
                                    None
                                })
                        }),
                        _ => None,
                    };
                    let diagnostics_before = diagnostics.len();
                    let to = match &spec {
                        DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some() => {
                            workspace_target
                        }
                        _ => workspace_target.or_else(|| {
                            index
                                .resolve_native_with_fallback(decl.ecosystem(), &entry.package_name, diagnostics)
                                .cloned()
                        }),
                    };
                    if let Some(to) = to {
                        let idx = edges.len();
                        let edge = DepEdge {
                            from: pkg.id.clone(),
                            to: to.clone(),
                            name: entry.name,
                            kind: entry.kind,
                            spec,
                            from_manifest: declaring_path,
                            inherited: entry.inherited,
                            locator: entry.locator,
                        };
                        edges.push(edge);

                        out_index.entry(pkg.id.clone()).or_default().push(idx);
                        in_index.entry(to).or_default().push(idx);
                    } else if let DepSpec::WorkspaceProtocol(workspace) = &spec {
                        let relative = workspace.relative_path().is_some();
                        // A cross-ecosystem name miss already warned; one warning per reference.
                        if relative || diagnostics.len() == diagnostics_before {
                            let form = if relative { "relative " } else { "" };
                            diagnostics.push(Diagnostic {
                                code: DiagnosticCode::UnknownPackage,
                                severity: DiagnosticSeverity::Warning,
                                message: format!(
                                    "{form}pnpm workspace dependency `{}` from `{}` does not identify an admitted npm workspace member",
                                    entry.name,
                                    decl.path.display()
                                ),
                                package: Some(pkg.id.clone()),
                                path: Some(decl.path.clone()),
                                escalated_by: None,
                                governed_by: None,
                            });
                        }
                    }
                }
            }
        }
    }

    (edges, out_index, in_index)
}

